begin;create extension if not exists pgtap with schema extensions;set local search_path=public,extensions;select plan(20);
insert into auth.users(id,email,raw_app_meta_data,raw_user_meta_data)values('1a000000-0000-4000-8000-000000000001','tax-owner@example.test','{}','{}'),('1a000000-0000-4000-8000-000000000002','tax-outsider@example.test','{}','{}');insert into public.workspaces(id,name,owner_id)values('2a000000-0000-4000-8000-000000000001','Tax Workspace','1a000000-0000-4000-8000-000000000001'),('2a000000-0000-4000-8000-000000000002','Other Tax Workspace','1a000000-0000-4000-8000-000000000002');update public.workspace_settings set opening_tax_reserve_balance=1000 where workspace_id='2a000000-0000-4000-8000-000000000001';
set local role authenticated;select throws_ok($$select public.mutate_tax_record('2a000000-0000-4000-8000-000000000001','1a000000-0000-4000-8000-000000000001','tax-denied-key','tax_payment','create',null,null,'x','{}')$$,'42501',null,'authenticated clients cannot call the service-role tax function');reset role;
create temporary table payment_create as select public.mutate_tax_record('2a000000-0000-4000-8000-000000000001','1a000000-0000-4000-8000-000000000001','tax-payment-create','tax_payment','create',null,null,'payment-hash','{"paymentDate":"2026-04-15","taxYear":2026,"quarter":1,"jurisdiction":"federal","amount":"350.10","paymentMethod":"EFTPS","confirmationReference":"ABC123","notes":"Q1 estimate","deviceId":"database-test"}')result;
select is((select result->>'version'from payment_create),'1','payment starts at version one');select is((select amount::text from public.tax_payments where id=(select(result->>'id')::uuid from payment_create)),'350.10','payment amount is exact');select is((select payment_method from public.tax_payments where id=(select(result->>'id')::uuid from payment_create)),'EFTPS','payment method is retained');select is((select count(*)::integer from public.sync_operations where client_mutation_id='tax-payment-create'),1,'payment writes a sync receipt');select is((select count(*)::integer from public.audit_events where request_id='tax-payment-create'),1,'payment writes an audit event');select is(public.mutate_tax_record('2a000000-0000-4000-8000-000000000001','1a000000-0000-4000-8000-000000000001','tax-payment-create','tax_payment','create',null,null,'payment-hash','{}')->>'id',(select result->>'id'from payment_create),'payment retry is idempotent');
create temporary table payment_update as select public.mutate_tax_record('2a000000-0000-4000-8000-000000000001','1a000000-0000-4000-8000-000000000001','tax-payment-update','tax_payment','update',(select(result->>'id')::uuid from payment_create),1,'payment-update-hash','{"paymentDate":"2026-04-15","taxYear":2026,"quarter":1,"jurisdiction":"federal","amount":"375.10","paymentMethod":"EFTPS","deviceId":"database-test"}')result;select is((select result->>'version'from payment_update),'2','payment update increments version');select throws_ok(format($$select public.mutate_tax_record('2a000000-0000-4000-8000-000000000001','1a000000-0000-4000-8000-000000000001','tax-payment-stale','tax_payment','update',%L,1,'stale','{"paymentDate":"2026-04-15","taxYear":2026,"quarter":1,"jurisdiction":"federal","amount":"400"}')$$,(select result->>'id'from payment_create)),'40001','Record version conflict','stale payment updates are rejected');
create temporary table movement_create as select public.mutate_tax_record('2a000000-0000-4000-8000-000000000001','1a000000-0000-4000-8000-000000000001','tax-movement-create','tax_reserve_movement','create',null,null,'movement-hash','{"movementDate":"2026-04-01","direction":"deposit","amount":"500.25","paymentMethod":"Transfer","note":"Quarterly funding","deviceId":"database-test"}')result;select is((select result->>'version'from movement_create),'1','reserve movement starts at version one');select is((select direction from public.tax_reserve_movements where id=(select(result->>'id')::uuid from movement_create)),'deposit','reserve direction is retained');select is((select count(*)::integer from public.sync_operations where client_mutation_id='tax-movement-create'),1,'movement writes a sync receipt');select is((select count(*)::integer from public.audit_events where request_id='tax-movement-create'),1,'movement writes an audit event');select is((select(1000+sum(case when direction='deposit'then amount else-amount end)-(select sum(amount)from public.tax_payments where workspace_id='2a000000-0000-4000-8000-000000000001'and deleted_at is null))::numeric(14,2)::text from public.tax_reserve_movements where workspace_id='2a000000-0000-4000-8000-000000000001'and deleted_at is null),'1125.15','reserve balance separates transfers from tax payments');
select throws_ok($$select public.mutate_tax_record('2a000000-0000-4000-8000-000000000001','1a000000-0000-4000-8000-000000000001','tax-payment-create','tax_reserve_movement','create',null,null,'payment-hash','{}')$$,'P0001','Idempotency key was already used for different content','idempotency keys cannot cross tax entities');
select public.mutate_tax_record('2a000000-0000-4000-8000-000000000001','1a000000-0000-4000-8000-000000000001','tax-payment-void','tax_payment','void',(select(result->>'id')::uuid from payment_create),2,'payment-void-hash','{"reason":"Duplicate estimated payment","deviceId":"database-test"}');select ok((select deleted_at is not null and void_reason='Duplicate estimated payment'from public.tax_payments where id=(select(result->>'id')::uuid from payment_create)),'payment void is non-destructive');select public.mutate_tax_record('2a000000-0000-4000-8000-000000000001','1a000000-0000-4000-8000-000000000001','tax-movement-void','tax_reserve_movement','void',(select(result->>'id')::uuid from movement_create),1,'movement-void-hash','{"reason":"Transfer was reversed","deviceId":"database-test"}');select ok((select deleted_at is not null and void_reason='Transfer was reversed'from public.tax_reserve_movements where id=(select(result->>'id')::uuid from movement_create)),'movement void is non-destructive');
select throws_ok($$select public.mutate_tax_record('2a000000-0000-4000-8000-000000000001','1a000000-0000-4000-8000-000000000002','tax-unauthorized','tax_payment','create',null,null,'x','{"paymentDate":"2026-04-15","taxYear":2026,"quarter":1,"jurisdiction":"federal","amount":"10"}')$$,'P0001','Not authorized to change tax records','service function rechecks membership');select throws_ok($$select public.mutate_tax_record('2a000000-0000-4000-8000-000000000001','1a000000-0000-4000-8000-000000000001','tax-invalid-jurisdiction','tax_payment','create',null,null,'x','{"paymentDate":"2026-04-15","taxYear":2026,"quarter":1,"jurisdiction":"invalid","amount":"10"}')$$,'23514',null,'unsupported jurisdiction is rejected by the database');select throws_ok($$select public.mutate_tax_record('2a000000-0000-4000-8000-000000000001','1a000000-0000-4000-8000-000000000001','tax-zero-amount','tax_reserve_movement','create',null,null,'x','{"movementDate":"2026-04-01","direction":"deposit","amount":"0"}')$$,'P0001','Tax record amount must be greater than zero','zero reserve movements are rejected');select * from finish();rollback;
